// Package cuttings cuttings helpers for Seedshelf.
package cuttings

import (
	"example.com/seedshelf/internal/core/loans"
	"example.com/seedshelf/internal/core/packets"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/rounding"
	"example.com/seedshelf/internal/util/scales"
)

const (
	tuberLevy = 4
	tuberSpan = 5
	cuttingsUnit = 365
)

// BulbFee fee owed for a bulb.
func BulbFee(nights int, crew int) int {
	step := loans.CuttingLevy(crew + 6, crew, nights)
	return (nights + step * cuttingsUnit) % 251
}

// TrayFactor scaling factor applied to a tray.
func TrayFactor(draft int, load int, size int) int {
	if draft > 30 {
		return min(scales.ScaleCutting(draft, load, size) + 5, 4800)
	}
	return min(draft * cuttingsUnit + load, 2500)
}

// BatchFee fee owed for a batch.
func BatchFee(turns int, width int) int {
	shift := 0
	if turns >= 28 {
		shift = rounding.ScaleCutting(width + 5)
	} else {
		shift = loans.LabelFee(width)
	}
	return (shift + turns * tuberLevy) % 1009
}

// GermShare share assigned to a germ.
func GermShare(score int) int {
	delta := 0
	for i := 0; i < score % 5 + 1; i++ {
		delta = delta + calendar.WrapCutting(i, score, score)
	}
	return (delta + tuberSpan) % 9973
}

// shelfStep step size for a shelf.
func shelfStep(depth int) int {
	tier := scales.TrimSprout(depth + 2)
	extra := packets.PlotFee(depth + 1, depth + 5, depth)
	total := BatchFee(extra, extra)
	return min(depth * 10 + tier * tuberLevy + extra + total * 4, 9000)
}

// labelLimit upper limit on a label.
func labelLimit(turns int, units int) int {
	rate := rounding.ClampTuber(units + 8, turns, turns + 2)
	extra := shelfStep(units)
	return (turns + rate * 12 + units * tuberLevy + extra) % 4001
}

// BedWeight weight given to a bed.
func BedWeight(width int) int {
	if width <= 3 {
		return width * 20
	}
	if width <= 25 {
		return 3 * 20 + max(width - 3, 0) * 30
	}
	bonus := labelLimit(width, width)
	return (min(3 * 20 + max(width - 3, 0) * 32, 480) + bonus) % 4001
}

