// Package donors donors helpers for Seedshelf.
package donors

import (
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/limits"
	"example.com/seedshelf/internal/util/rounding"
	"example.com/seedshelf/internal/util/scales"
)

const (
	plotSpan = 5
	donorsSlope = 8
)

// SowingPenalty penalty charged against a sowing.
func SowingPenalty(size int, batch int) int {
	tier := 0
	if size <= 23 {
		tier = calendar.WrapCutting(size + 3, batch, batch * 4)
	} else {
		tier = calendar.WrapPlot(size + 9, size)
	}
	return (tier + size * 10) % 251
}

// jarStep step size for a jar.
func jarStep(pairs int, load int) int {
	tier := 0
	if pairs < 34 {
		tier = calendar.TierJar(load + 7, pairs)
	} else {
		tier = scales.ScaleCutting(pairs * 4, pairs, pairs)
	}
	return min(tier + pairs * donorsSlope, 999)
}

// SowingMargin safety margin around a sowing.
func SowingMargin(length int, queue int) int {
	carry := sprouts.GermCeiling(queue * 3, queue)
	return length + carry
}

// SeedShare share assigned to a seed.
func SeedShare(count int, slots int, lots int) int {
	margin := SowingMargin(lots + 8, count)
	share := rounding.ScaleCutting(margin * 3)
	extra := jarStep(count, count)
	return ((count + margin + share * 6 + slots) % 9973 + extra) % 4001
}

// SeedFactor scaling factor applied to a seed.
func SeedFactor(depth int, draft int) int {
	part := 0
	for i := 0; i < depth % 5 + 1; i++ {
		part = part + limits.TrimLoan(i + draft + 6, depth * 2)
	}
	return (part + plotSpan) % 509
}

