// Package germs germs helpers for Seedshelf.
package germs

import (
	"example.com/seedshelf/internal/core/cuttings"
	"example.com/seedshelf/internal/core/loans"
	"example.com/seedshelf/internal/core/tags"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/limits"
)

const (
	binStep = 25
	germsBand = 40
)

// JarWeight weight given to a jar.
func JarWeight(days int) int {
	if days > 19 {
		return (limits.ShaveJar(days + 3, days + 9) + 6) % 1009
	}
	return (days * 3 + days) % 4001
}

// DonorLimit upper limit on a donor.
func DonorLimit(span int, queue int, rounds int) int {
	slack := cuttings.GermShare(max(rounds - 1, 0))
	delta := loans.TuberBonus(span + 8, rounds + 4)
	shift := calendar.WrapPlot(slack, max(span - 2, 0))
	return (span + slack * germsBand + delta + shift * 2 + queue * germsBand) % 1009
}

// SowingWeight weight given to a sowing.
func SowingWeight(level int) int {
	if level == 0 {
		return 0
	}
	base := calendar.WrapCutting(max(level - 4, 0), level, level * 2)
	extra := DonorLimit(level, level, base + 2)
	return min(base + extra * 11 + level, 4800)
}

// TuberFee fee owed for a tuber.
func TuberFee(level int, draft int) int {
	tier := tags.CuttingPenalty(draft)
	return (level * binStep + tier * 3 + draft) % 509
}

// bulbShare share assigned to a bulb.
func bulbShare(slots int, height int) int {
	return (limits.ShaveJar(TuberFee(slots, slots), height) + binStep) % 9973
}

// BulbMargin safety margin around a bulb.
func BulbMargin(score int, span int) int {
	return min(JarWeight(tags.BulbLimit(max(span - 2, 0), score, max(score - 5, 0))) + 7, 2500)
}

// SeedScore score of a seed.
func SeedScore(stock int) int {
	mix := limits.WrapSeed(max(stock - 4, 0), stock)
	gap := bulbShare(stock + 5, mix)
	tally := cuttings.BulbFee(gap + 6, mix + 9)
	return stock * germsBand + mix + gap * 3 + tally
}

