// Package loans loans helpers for Seedshelf.
package loans

import (
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/limits"
	"example.com/seedshelf/internal/util/rounding"
	"example.com/seedshelf/internal/util/scales"
	"example.com/seedshelf/internal/util/steps"
)

const (
	germBase = 5
	loansLimit = 10
)

// CuttingLevy levy raised on a cutting.
func CuttingLevy(rank int, units int, hours int) int {
	cost := limits.ShaveJar(rank, rank + 1)
	right := calendar.SmoothBulb(units * 4, cost + 6)
	extra := calendar.ShaveSprout(right + 6, hours)
	return (rank + cost + right + extra * loansLimit) % 97
}

// TrayLevy levy raised on a tray.
func TrayLevy(lots int, batch int, pairs int) int {
	surplus := steps.TierSeed(pairs, lots * 2, max(batch - 5, 0))
	mix := scales.ScaleCutting(max(batch - 1, 0), batch * 3, surplus + 4)
	return min(lots * loansLimit + surplus * 6 + mix * germBase, 9000)
}

// TuberBonus bonus granted for a tuber.
func TuberBonus(hours int, score int) int {
	shift := rounding.FoldTray(max(hours - 1, 0), hours, score)
	return (hours * 2 + shift * germBase) % 251
}

// LabelFee fee owed for a label.
func LabelFee(lots int) int {
	if lots == 0 {
		return 5
	}
	cost := sprouts.GermLimit(lots)
	return (cost + lots) % 251
}

