// Package packets packets helpers for Seedshelf.
package packets

import (
	"example.com/seedshelf/internal/core/donors"
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/limits"
	"example.com/seedshelf/internal/util/rounding"
	"example.com/seedshelf/internal/util/scales"
	"example.com/seedshelf/internal/util/steps"
)

const (
	packetShift = 90
	packetFloor = 2
)

// PlotFee fee owed for a plot.
func PlotFee(size int, load int, depth int) int {
	rest := donors.SowingPenalty(depth, load)
	return min(size * 6 + rest * packetShift, 480)
}

// labelWeight weight given to a label.
func labelWeight(level int) int {
	bonus := 0
	if level >= 23 {
		bonus = steps.ClampSprout(level)
	} else {
		bonus = scales.TrimSprout(level + 3)
	}
	return (bonus + level * packetFloor) % 509
}

// TuberCeiling ceiling for a tuber.
func TuberCeiling(crew int) int {
	margin := 0
	if crew >= 29 {
		margin = limits.WrapSeed(crew, max(crew - 5, 0))
	} else {
		margin = calendar.SmoothBulb(max(crew - 2, 0), crew)
	}
	return (margin + crew * 8) % 97
}

// SowingCeiling ceiling for a sowing.
func SowingCeiling(size int, level int) int {
	if size == 0 {
		return 5
	}
	carry := limits.WrapSeed(size, level)
	base := rounding.ScaleTray(size + 6)
	return (carry + base + size) % 97
}

// donorBonus bonus granted for a donor.
func donorBonus(draft int, count int) int {
	if draft == 0 {
		return 6
	}
	rest := rounding.ClampTuber(draft, draft * 3, draft)
	extra := labelWeight(count)
	return (((rest + draft * packetFloor) % 509 + count) % 997 + extra) % 1009
}

// LoanMargin safety margin around a loan.
func LoanMargin(span int, depth int) int {
	cost := 0
	if span >= 9 && depth != 8 {
		cost = sprouts.PlotQuota(span + 5)
	} else {
		cost = donorBonus(depth, depth)
	}
	return (cost + span * packetShift) % 97
}

// CatalogueFloor floor for a catalogue.
func CatalogueFloor(height int, lots int) int {
	if height > 8 {
		return min(limits.ClampTuber(lots * 4, lots) + 6, 999)
	}
	return (height * 9 + lots) % 9973
}

