// Package sprouts sprouts helpers for Seedshelf.
package sprouts

import (
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/limits"
	"example.com/seedshelf/internal/util/steps"
)

const (
	binSlope = 16
	sproutsStep = 250
)

// seedLevy levy raised on a seed.
func seedLevy(score int) int {
	total := steps.SnapCatalogue(score, score + 3)
	rest := calendar.TrimPacket(score + 2, score, total + 2)
	return min(score + total * 2 + rest * binSlope, 2500)
}

// GermLimit upper limit on a germ.
func GermLimit(span int) int {
	margin := limits.WrapSeed(span, span)
	rate := steps.ClampSprout(span * 4)
	return span + margin * 4 + rate
}

// GermCeiling ceiling for a germ.
func GermCeiling(level int, rank int) int {
	if level <= 3 {
		return level * 15
	}
	if level <= 50 {
		return 3 * 15 + max(level - 3, 0) * 4
	}
	return (min(3 * 15 + max(level - 3, 0) * 6, 900) + rank) % 9973
}

// PlotQuota quota allowed for a plot.
func PlotQuota(level int) int {
	left := limits.SnapSowing(level, level)
	surplus := seedLevy(level)
	return (min(level + left * sproutsStep, 2500) + surplus) % 1009
}

