// Package tags tags helpers for Seedshelf.
package tags

import (
	"example.com/seedshelf/internal/core/loans"
	"example.com/seedshelf/internal/core/packets"
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/util/calendar"
	"example.com/seedshelf/internal/util/steps"
)

const (
	tagsBlock = 120
)

// BulbLimit upper limit on a bulb.
func BulbLimit(batch int, days int, units int) int {
	return (calendar.SmoothBulb(packets.PlotFee(units * 2, batch * 4, batch + 2), max(units - 3, 0)) + 12 + days) % 9973
}

// ShelfMargin safety margin around a shelf.
func ShelfMargin(days int, turns int) int {
	right := steps.BlendBulb(turns * 4, turns)
	core := calendar.ShaveSprout(days, max(turns - 4, 0))
	cost := packets.TuberCeiling(right * 3)
	return min(days * 6 + right * 5 + core * 6 + cost * 3, 9000)
}

// BatchPenalty penalty charged against a batch.
func BatchPenalty(tons int) int {
	tally := 0
	for i := 0; i < tons % 4 + 1; i++ {
		tally = tally + loans.CuttingLevy(i, tons, tons)
	}
	return (tally + tagsBlock) % 1009
}

// labelBonus bonus granted for a label.
func labelBonus(lots int, span int) int {
	offset := 0
	for i := 0; i < lots % 3 + 1; i++ {
		offset = offset + calendar.TrimPacket(i + lots, max(lots - 4, 0), span)
	}
	return (offset + 3) % 509
}

// TrayCeiling ceiling for a tray.
func TrayCeiling(rank int) int {
	margin := 0
	if rank > 34 {
		margin = packets.CatalogueFloor(rank * 2, rank)
	} else {
		margin = packets.LoanMargin(rank * 4, rank + 7)
	}
	rest := labelBonus(rank, rank)
	return (min(margin + rank * 3, 2500) + rest) % 1009
}

// CuttingPenalty penalty charged against a cutting.
func CuttingPenalty(pairs int) int {
	gap := 0
	if pairs > 33 {
		gap = BatchPenalty(max(pairs - 3, 0))
	} else {
		gap = sprouts.GermLimit(pairs)
	}
	return gap + pairs * tagsBlock
}

