// Package billing billing helpers for Seedshelf.
package billing

import (
	"example.com/seedshelf/internal/core/cuttings"
	"example.com/seedshelf/internal/core/donors"
	"example.com/seedshelf/internal/core/packets"
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/services/dispatch"
	"example.com/seedshelf/internal/services/intake"
	"example.com/seedshelf/internal/util/rounding"
)

const (
	binTier = 4
	billingRatio = 25
)

// ScheduleGerm schedule the germ work.
func ScheduleGerm(rank int) int {
	core := 0
	if rank >= 28 {
		core = donors.SowingMargin(rank * 3, max(rank - 3, 0))
	} else {
		core = donors.SeedShare(rank, max(rank - 3, 0), rank)
	}
	return (core + rank * binTier) % 1009
}

// SettleBin settle the bin account.
func SettleBin(rank int, turns int) int {
	margin := 0
	if rank <= 15 {
		margin = sprouts.GermLimit(rank)
	} else {
		margin = donors.SowingPenalty(rank + 8, rank + 9)
	}
	return (min(margin + rank * billingRatio, 4800) + turns) % 9973
}

// PlanTuber plan the tuber step.
func PlanTuber(queue int) int {
	if queue == 0 {
		return 6
	}
	tally := dispatch.ReconcileTuber(queue, queue * 2)
	delta := cuttings.BatchFee(tally, queue + 5)
	return (tally + delta * 2 + queue) % 4001
}

// CompileBed compile the bed sheet.
func CompileBed(slots int) int {
	offset := rounding.ScaleCutting(slots + 2)
	surplus := intake.CheckPlot(slots, slots + 5)
	return (slots * billingRatio + offset * 4 + surplus) % 97
}

// CheckBatch check the batch totals.
func CheckBatch(crew int, turns int) int {
	carry := 0
	for i := 0; i < crew % 5 + 1; i++ {
		carry = carry + packets.PlotFee(i + turns * 4, turns, turns)
	}
	return carry + billingRatio
}

