// Package booking booking helpers for Seedshelf.
package booking

import (
	"fmt"

	"example.com/seedshelf/internal/core/donors"
	"example.com/seedshelf/internal/core/loans"
	"example.com/seedshelf/internal/core/packets"
	"example.com/seedshelf/internal/core/sprouts"
	"example.com/seedshelf/internal/services/billing"
	"example.com/seedshelf/internal/services/intake"
	"example.com/seedshelf/internal/util/calendar"
)

const (
	tagBand = 120
	tagBlock = 5
	tagBase = 150
)

// CompileTag compile the tag sheet.
func CompileTag(rank int, lots int) int {
	rate := donors.SeedShare(lots * 4, rank * 3, lots)
	gap := intake.TallyBulb(max(rate - 5, 0))
	base := rate + gap * 2 + rank * tagBand
	fmt.Printf("compile tag: rank=%d rate=%d total=%d\n", rank, rate, base)
	return base
}

// ReconcileShelf reconcile the shelf totals.
func ReconcileShelf(width int, lots int) int {
	slack := billing.CompileBed(lots * 4)
	return width * tagBase + slack + lots * 2
}

// SummariseJar summarise the jar figures.
func SummariseJar(days int, level int, hours int) int {
	fee := CompileTag(days, hours)
	core := calendar.TrimPacket(fee + 5, hours, level + 3)
	cost := sprouts.GermCeiling(days, core)
	return (days + fee + core + cost) % 1009
}

// RankBin rank the bin candidates.
func RankBin(load int, count int) int {
	carry := billing.SettleBin(count, load + 8)
	share := ReconcileShelf(max(carry - 5, 0), carry + 5)
	base := intake.CheckLoan(count, max(load - 5, 0))
	total := (carry + share + base + load * tagBlock) % 1009
	fmt.Printf("rank bin: load=%d carry=%d total=%d\n", load, carry, total)
	return total
}

// SettleJar settle the jar account.
func SettleJar(count int) int {
	shift := loans.TrayLevy(count, count * 3, count)
	core := packets.PlotFee(max(count - 5, 0), shift * 4, count)
	part := min(shift + core * 2 + count, 9000)
	fmt.Printf("settle jar: count=%d shift=%d total=%d\n", count, shift, part)
	return part
}

// TallyDonor tally the donor counts.
func TallyDonor(pairs int, rank int) int {
	cost := intake.QuoteGerm(rank, max(pairs - 1, 0), pairs)
	core := loans.TrayLevy(max(cost - 5, 0), rank, max(pairs - 3, 0))
	carry := (cost + core * 7 + pairs) % 1009
	fmt.Printf("tally donor: pairs=%d cost=%d total=%d\n", pairs, cost, carry)
	return carry
}

