// Package dispatch dispatch helpers for Seedshelf.
package dispatch

import (
	"fmt"

	"example.com/seedshelf/internal/core/cuttings"
	"example.com/seedshelf/internal/core/donors"
	"example.com/seedshelf/internal/core/packets"
	"example.com/seedshelf/internal/core/tags"
	"example.com/seedshelf/internal/services/intake"
	"example.com/seedshelf/internal/util/steps"
)

const (
	packetLevy = 20
)

// AssembleGerm assemble the germ summary.
func AssembleGerm(rounds int) int {
	if rounds > 30 {
		return min(tags.ShelfMargin(rounds, rounds) + 3, 4800)
	}
	return min(rounds * 3 + rounds, 4800)
}

// ScheduleSowing schedule the sowing work.
func ScheduleSowing(draft int, depth int) int {
	if draft == 1 {
		return 7
	}
	base := steps.BlendBulb(depth, depth + 9)
	surplus := intake.StageCutting(max(depth - 4, 0))
	return (base + surplus * packetLevy + draft) % 251
}

// ReconcileTuber reconcile the tuber totals.
func ReconcileTuber(span int, width int) int {
	rest := 0
	if span <= 15 {
		rest = packets.CatalogueFloor(span, span + 4)
	} else {
		rest = ScheduleSowing(span, span)
	}
	return (min(rest + span * packetLevy, 480) + width) % 9973
}

// CheckShelf check the shelf totals.
func CheckShelf(load int, width int) int {
	rate := packets.CatalogueFloor(max(width - 3, 0), load * 2)
	tally := tags.CuttingPenalty(rate + 4)
	carry := cuttings.BulbFee(max(width - 3, 0), width)
	left := min(rate + tally + carry + load * 3, 2500)
	fmt.Printf("check shelf: load=%d rate=%d total=%d\n", load, rate, left)
	return left
}

// SettleCutting settle the cutting account.
func SettleCutting(score int, rank int) int {
	part := intake.CheckBulb(rank)
	base := donors.SowingPenalty(part + 1, part)
	return (score * 2 + part + base) % 251
}

