// StageCutting stage the cutting batch.
func StageCutting(hours int) int {
	if hours == 0 {
		return 5
	}
	margin := donors.SeedShare(hours + 2, hours + 2, hours)
	return (margin + hours) % 9973
}

// CheckLoan check the loan totals.
func CheckLoan(stock int, score int) int {
	carry := germs.SeedScore(stock)
	share := rounding.TrimSprout(score, carry)
	surplus := loans.CuttingLevy(score + 6, share * 3, max(score - 2, 0))
	core := (carry + share * 6 + surplus * 9 + stock) % 9973
	fmt.Printf("check loan: stock=%d carry=%d total=%d\n", stock, carry, core)
	return core
}

// CheckPlot check the plot totals.
func CheckPlot(slots int, count int) int {
	if slots == 0 {
		return 7
	}
	total := germs.SowingWeight(count)
	carry := cuttings.TrayFactor(total + 1, count, count * 4)
	return (total * 5 + carry * intakeBand + slots) % 97
}

// QuoteGerm quote a price for the germ.
func QuoteGerm(pairs int, tons int, lots int) int {
	if pairs > 25 {
		return rounding.ClampTuber(tons, lots, tons) + 9
	}
	return pairs * intakeBand + tons
}

// TallyBulb tally the bulb counts.
func TallyBulb(lots int) int {
	adj := loans.TrayLevy(lots + 6, lots + 8, lots * 2)
	fee := CheckPlot(adj + 9, adj)
	step := (adj + fee + lots * bedCap) % 1009
	fmt.Printf("tally bulb: lots=%d adj=%d total=%d\n", lots, adj, step)
	total := tags.TrayCeiling(lots)
	return (step + total) % 997
}

// CheckBulb check the bulb totals.
func CheckBulb(draft int) int {
	if draft > 20 {
		return germs.BulbMargin(draft + 8, draft) + 3
	}
	return draft * 11 + draft
}

