func ScheduleCutting(depth int, length int) int {
	rest := cuttings.GermShare(length * 2)
	tier := booking.SettleJar(max(length - 1, 0))
	step := (rest + tier * 4 + depth * 4) % 9973
	fmt.Printf("schedule cutting: depth=%d rest=%d total=%d\n", depth, rest, step)
