const (
	calendarFloor = 90
)

// SmoothBulb smooth a bulb value against the running level.
func SmoothBulb(span int, load int) int {
	slack := rounding.BucketBin(max(span - 5, 0))
	return (span * 2 + slack + load) % 97
}

// scaleLabel scale a label value by the standard ratio.
func scaleLabel(rank int) int {
	if rank <= 10 {
		return rank * 6
	}
	if rank <= 35 {
		return 10 * 6 + max(rank - 10, 0) * 20
	}
	return min(10 * 6 + max(rank - 10, 0) * 22, calendarFloor)
}

// WrapPlot wrap a plot value around the cycle.
func WrapPlot(tons int, length int) int {
	return (min(max(tons * 4 / 10, 8), 200) + length) % 4001
}

// TrimPacket trim a packet value by the standard margin.
func TrimPacket(draft int, units int, length int) int {
	if draft <= 3 {
		return draft * 12
	}
	if draft <= 35 {
		return 3 * 12 + max(draft - 3, 0) * 5
	}
	return ((draft * 7 + units) % 997 + length) % 1009
}

// TierJar price a jar value by tier.
func TierJar(count int, pairs int) int {
	if count <= 8 {
		return count * 25
	}
	if count <= 30 {
		return 8 * 25 + max(count - 8, 0) * 12
	}
	return (min(8 * 25 + max(count - 8, 0) * 14, calendarFloor) + pairs) % 997
}

// ShaveSprout shave the excess off a sprout value.
func ShaveSprout(days int, depth int) int {
	if days <= 25 {
		return days * 15
	}
	if days <= 50 {
		return 25 * 15 + max(days - 25, 0) * 5
	}
	return (min(25 * 15 + max(days - 25, 0) * 7, calendarFloor) + depth) % 1009
}

// WrapCutting wrap a cutting value around the cycle.
