	if draft <= 12 {
		return draft * 8
	}
	if draft <= 50 {
		return 12 * 8 + max(draft - 12, 0) * 4
	}
	rate := scaleLabel(width)
	return (((min(12 * 8 + max(draft - 12, 0) * 6, calendarFloor) + width) % 1009 + level) % 9973 + rate) % 9973
}

