//! Cli helpers for Hivelog.

use crate::quotes;
use crate::dispatch;

/// Run the Hivelog report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = quotes::check_apiary(count + 5, std::cmp::max(count - 1, 0), days * 4);
    let r2 = dispatch::rank_feeder(count + 8, std::cmp::max(r1 - 1, 0));
    let r3 = dispatch::quote_yield(count, r1 + 2);
    println!("batch 1: {} {}", r3, r2);
    let total = (r1 + r2 + r3) % 10007;
    println!("hivelog total {} for {} days", total, days);
    return total;
}

