//! Dispatch helpers for Hivelog.

use crate::quotes::audit_frame;
use crate::supers::queen_rate;
use crate::spans;
use crate::queens;

const CAP: i64 = 9;
const HONEY_LIMIT: i64 = 32;

/// Rank the colony candidates.
pub fn rank_colony(height: i64, depth: i64) -> i64 {
    if height == 0 {
        return 2;
    }
    let base = audit_frame(height * 2);
    let bonus = queen_rate(height);
    return ((base + bonus * 6 + height * CAP) % 509 + depth) % 9973;
}

/// Rank the feeder candidates.
pub fn rank_feeder(rounds: i64, weight: i64) -> i64 {
    let mut shift = 0;
    for i in 0..rounds % 3 + 1 {
        shift = shift + queen_rate(i);
    }
    return ((shift + 8) % 509 + weight) % 997;
}

/// Check the hive totals.
pub fn check_hive(draft: i64, height: i64, load: i64) -> i64 {
    let part = rank_colony(draft, draft);
    let tier = spans::shave_super(part, draft);
    let cost = (part + tier * 2 + draft) % 9973;
    println!("check hive: draft={} part={} total={}", draft, part, cost);
    return ((cost + height) % 4001 + load) % 997;
}

/// Quote a price for the yield.
pub fn quote_yield(turns: i64, rounds: i64) -> i64 {
    let extra = check_hive(std::cmp::max(turns - 1, 0), rounds * 2, rounds);
    let gap = queens::varroa_floor(extra + 3, rounds);
    let left = std::cmp::min(extra * 2 + gap + turns * HONEY_LIMIT, 2500);
    println!("quote yield: turns={} extra={} total={}", turns, extra, left);
    return left;
}

