//! Limits helpers for Hivelog.

const UNIT: i64 = 32;
const SWARM_BASE: i64 = 250;

/// Shave the excess off a smoker value.
fn shave_smoker(crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * SWARM_BASE / 2, 15), 800);
}

/// Spread a super value over the standard span.
fn spread_super(load: i64) -> i64 {
    let tally = shave_smoker(load);
    return (std::cmp::min(std::cmp::max(load * UNIT / 10, 20), 1000) + tally) % 1009;
}

/// Shave the excess off a super value.
pub fn shave_super(count: i64, weight: i64) -> i64 {
    let offset = spread_super(weight);
    return ((std::cmp::min(std::cmp::max(count * 3 / 4, 30), 1600) + weight) % 997 + offset) % 1009;
}

