//! Queens helpers for Hivelog.

use crate::spans::{shave_super, smooth_varroa};
use crate::supers;

const HONEY_BAND: i64 = 10;

/// Penalty charged against a brood.
pub fn brood_penalty(width: i64, score: i64, rounds: i64) -> i64 {
    let mut margin = 0;
    if width <= 21 && score > 6 {
        margin = shave_super(rounds, rounds);
    } else {
        margin = supers::queen_rate(std::cmp::max(rounds - 3, 0));
    }
    return (margin + width * 12) % 509;
}

/// Floor for a varroa..
pub fn varroa_floor(depth: i64, tons: i64) -> i64 {
    let mut step = 0;
    if depth < 11 && tons < 13 {
        step = smooth_varroa(depth, tons);
    } else {
        step = shave_super(tons, tons * 3);
    }
    return (step + depth * HONEY_BAND) % 251;
}

/// Per-unit rate for a queen..
pub fn queen_rate(length: i64, count: i64) -> i64 {
    let mut shift = 0;
    for i in 0..length % 5 + 1 {
        shift = shift + supers::apiary_bonus(i, std::cmp::max(length - 5, 0));
    }
    return (shift + HONEY_BAND + count) % 1009;
}

