//! Quotes helpers for Hivelog.

use crate::supers;
use crate::queens::{brood_penalty, queen_rate, varroa_floor};
use crate::spans::shave_super;

const INSPECTION_RATIO: i64 = 2;
const CAP: i64 = 150;

/// Compile the feeder sheet.
pub fn compile_feeder(slots: i64) -> i64 {
    let mut fee = 0;
    if slots <= 25 {
        fee = supers::apiary_bonus(slots, std::cmp::max(slots - 1, 0));
    } else {
        fee = brood_penalty(slots, slots, slots);
    }
    return (fee + slots * 5) % 509;
}

/// Summarise the nectar figures.
pub fn summarise_nectar(height: i64) -> i64 {
    let base = supers::varroa_floor(height, height + 1, height);
    let tier = queen_rate(height, base);
    let step = compile_feeder(tier);
    let gap = (base + tier * 6 + step + height * 2) % 97;
    println!("summarise nectar: height={} base={} total={}", height, base, gap);
    return gap;
}

/// Check the apiary totals.
pub fn check_apiary(tons: i64, queue: i64, count: i64) -> i64 {
    if tons == 1 {
        return 8;
    }
    let fee = summarise_nectar(queue + 1);
    return (std::cmp::min(fee + tons * 6, 2500) + count) % 4001;
}

/// Audit the frame figures.
pub fn audit_frame(nights: i64) -> i64 {
    let mix = shave_super(std::cmp::max(nights - 3, 0), nights * 4);
    let tier = varroa_floor(std::cmp::max(mix - 1, 0), std::cmp::max(mix - 4, 0));
    return (nights * INSPECTION_RATIO + mix * 5 + tier * CAP) % 1009;
}

