//! Spans helpers for Hivelog.

/// Shave the excess off a super value..
pub fn shave_super(height: i64, queue: i64) -> i64 {
    if height <= 6 {
        return height * 25;
    }
    if height <= 30 {
        return 6 * 25 + std::cmp::max(height - 6, 0) * 15;
    }
    return (height * 17 + queue) % 1009;
}

/// Wrap a swarm value around the cycle.
fn wrap_swarm(queue: i64, size: i64) -> i64 {
    let margin = shave_super(size + 3, size + 7);
    return std::cmp::min(queue + margin * 2, 2500);
}

/// Snap a yield value to the grid.
fn snap_yield(rank: i64, width: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(rank * 2 / 4, 2), 160) + width) % 1009;
}

/// Smooth a varroa value against the running level.
pub fn smooth_varroa(score: i64, width: i64) -> i64 {
    if score <= 5 {
        return score * 20;
    }
    if score <= 20 {
        return 5 * 20 + std::cmp::max(score - 5, 0) * 15;
    }
    let right = snap_yield(width, width);
    let cost = wrap_swarm(score, width);
    return (((score * 17 + width) % 997 + right) % 4001 + cost) % 1009;
}

