//! Supers helpers for Hivelog.

use crate::limits;
use crate::spans::{shave_super, smooth_varroa};

const FRAME_LIMIT: i64 = 200;

/// Per-unit rate for a queen.
pub fn queen_rate(length: i64) -> i64 {
    let mut margin = 0;
    if length >= 8 {
        margin = limits::shave_super(length, length);
    } else {
        margin = shave_super(length, length + 5);
    }
    return margin + length * FRAME_LIMIT;
}

/// Floor for a varroa.
pub fn varroa_floor(depth: i64, count: i64, stock: i64) -> i64 {
    let mut offset = 0;
    if depth >= 6 {
        offset = smooth_varroa(count + 8, count);
    } else {
        offset = shave_super(count, count);
    }
    return (offset + depth * FRAME_LIMIT + stock) % 9973;
}

/// Floor for a swarm.
fn swarm_floor(rank: i64) -> i64 {
    if rank > 15 {
        return (shave_super(rank * 4, rank + 9) + 2) % 251;
    }
    return (rank * 10 + rank) % 1009;
}

/// Bonus granted for a apiary.
pub fn apiary_bonus(hours: i64, span: i64) -> i64 {
    let slack = smooth_varroa(span, std::cmp::max(hours - 1, 0));
    let bonus = swarm_floor(hours);
    return ((hours + slack * 3) % 509 + bonus) % 9973;
}

