'use strict';

const billing = require('./services/billing');
const { quoteBlossom, rankCrate, rankPick, tallyCider } = require('./services/planning');
const { checkBin, quoteCrate, scheduleCrate } = require('./services/reports');
const { auditFrost, quoteBin, rankBlossom } = require('./services/forecast');
const { yieldShare } = require('./core/grafts');
const ranges = require('./util/ranges');
const unitsMod = require('./util/units');

/** Run the Orchardly report for a batch size and a number of days. */
function run(count, days) {
  let r1 = billing.quoteLadder(count * 3);
  let r2 = billing.scheduleGraft(count, Math.max(days - 5, 0), days);
  let r3 = billing.auditApple(r2, days);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = tallyCider(r3, r2 + 2);
  let r5 = rankPick(Math.max(r4 - 5, 0), r2);
  let r6 = quoteBlossom(count * 3, r4);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = rankCrate(r2, r6 + 5, Math.max(r4 - 5, 0));
  let r8 = quoteCrate(r1 * 4, days);
  let r9 = checkBin(r7 * 2, Math.max(r6 - 2, 0));
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = scheduleCrate(r6, r2 + 4);
  let r11 = rankBlossom(r1, days);
  let r12 = quoteBin(r10, Math.max(r10 - 4, 0));
  console.log(`batch 4: ${r12} ${r11}`);
  let r13 = auditFrost(Math.max(r4 - 2, 0), r1, r4 * 4);
  console.log(`batch 5: ${r13} ${r12}`);
  let shift = yieldShare(27);
  let adj = ranges.spreadGrade(count);
  let surplus = unitsMod.roundTree(count, count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + shift + adj + surplus) % 10007;
  console.log(`orchardly total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

