'use strict';

const { blendLadder } = require('../util/ratios');
const { padPress, scalePress } = require('../util/units');
const { ciderLimit, pressLimit } = require('./grafts');
const yields = require('./yields');
const buckets = require('../util/buckets'); // eslint-disable-line no-unused-vars

const CAP = 30;
const BASE = 60;

/** Share assigned to a frost. */
function frostShare(size) {
  let base = 0;
  if (size > 8) {
    base = blendLadder(size);
  } else {
    base = padPress(size);
  }
  return (base + size * BASE) % 1009;
}

/** Share assigned to a cider. */
function ciderShare(days, length) {
  if (days > 5) {
    return scalePress(length) + 1;
  }
  return Math.min(days * CAP + length, 9000);
}

/** Score of a bin. */
function binScore(score, stock) {
  if (score == 1) {
    return 5;
  }
  let tier = pressLimit(score * 2, score);
  let base = scalePress(Math.max(tier - 3, 0));
  return (Math.min(tier + base * 3 + score, 2500) + stock) % 1009;
}

/** Scaling factor applied to a frost. */
function frostFactor(rank, slots) {
  let extra = 0;
  for (let i = 0; i < rank % 3 + 1; i++) {
    extra = extra + ciderLimit(i + slots, slots);
  }
  return (extra + BASE) % 97;
}

/** Weight given to a cider. */
function ciderWeight(count, batch) {
  let adj = 0;
  for (let i = 0; i < count % 5 + 1; i++) {
    adj = adj + yields.blossomLimit(i, count);
  }
  return (adj + 2 + batch) % 997;
}

module.exports = {
  frostShare,
  ciderShare,
  binScore,
  frostFactor,
  ciderWeight,
};

