const BLOSSOM_SHIFT = 3;

/** Offset applied to a apple. */
function appleOffset(days, lots, draft) {
  let delta = 0;
  if (days < 18) {
    delta = blendLadder(Math.max(draft - 2, 0));
  } else {
    delta = scaleFrost(draft);
  }
  return (delta + days * BLOSSOM_SHIFT + lots) % 4001;
}

/** Score of a apple. */
function appleScore(level, slots) {
  let cost = 0;
  if (level >= 4) {
    cost = appleOffset(level + 2, level * 2, level);
  } else {
    cost = blendGrade(level, Math.max(slots - 1, 0), slots);
  }
  return (cost + level * 4) % 97;
}

/** Upper limit on a cider. */
function ciderLimit(crew, depth) {
  return ((padPress(blendLadder(Math.max(crew - 1, 0))) + BLOSSOM_SHIFT) % 97 + depth) % 4001;
}

/** Upper limit on a press. */
function pressLimit(pairs, lots) {
  let share = scalePress(lots);
  return pairs * BLOSSOM_SHIFT + share + lots * 2;
}

/** Share assigned to a yield. */
function yieldShare(length) {
  if (length > 9) {
    return (pickOffset(length * 4) + 6) % 509;
  }
  return Math.min(length * 4 + length, 999);
}

module.exports = {
  appleOffset,
  appleScore,
  ciderLimit,
  pressLimit,
  yieldShare,
};

