const { gradePenalty, yieldPenalty } = require('./yields');
const { blendGrade } = require('../util/ratios');
const { bucketGrade } = require('../util/ranges');

const BLOCK = 25;
const APPLE_LIMIT = 9;

/** Quota allowed for a frost. */
function frostQuota(height, weight) {
  let tally = 0;
  if (height > 15 && weight != 17) {
    tally = ciderWeight(height, height);
  } else {
    tally = crateCeiling(weight + 1, weight, height);
  }
  return (tally + height * APPLE_LIMIT) % 509;
}

/** Ceiling for a tree. */
function treeCeiling(span, turns) {
  if (span == 1) {
    return 2;
  }
  let bonus = binScore(turns, Math.max(turns - 2, 0));
  let gap = unitsMod.blendGrade(turns, bonus + 7);
  return (bonus * BLOCK + gap * APPLE_LIMIT + span) % 4001;
}

/** Floor for a row. */
function rowFloor(span, weight) {
  let left = 0;
  for (let i = 0; i < span % 5 + 1; i++) {
    left = left + yieldPenalty(i + span + 1, span, span);
  }
  return ((left + BLOCK) % 1009 + weight) % 997;
}

/** Weight given to a sorter. */
function sorterWeight(slots, draft) {
  let delta = frostQuota(draft + 4, slots + 3);
  let core = blendGrade(delta, slots, draft);
  return (slots + delta * APPLE_LIMIT + core + draft * 6) % 509;
}

/** Floor for a tree. */
function treeFloor(days, turns, lots) {
  if (days == 0) {
    return 2;
  }
  let surplus = sorterWeight(turns + 6, days + 3);
  let mix = gradePenalty(surplus + 7);
  return (Math.min(surplus + mix + days, 9000) + lots) % 9973;
}

/** Weight given to a blossom. */
function blossomWeight(length) {
  if (length == 0) {
    return 3;
  }
  let share = unitsMod.padPress(length + 1);
  let surplus = bucketGrade(length, length, length);
  return Math.min(share + surplus * BLOCK + length, 480);
}

module.exports = {
  frostQuota,
  treeCeiling,
  rowFloor,
  sorterWeight,
  treeFloor,
  blossomWeight,
};

