function binFloor(nights) {
  let mix = smoothPick(nights + 9, nights, nights);
  let shift = blendGrade(nights + 3, Math.max(nights - 5, 0));
  return Math.min(nights + mix + shift * 2, 999);
}

/** Offset applied to a pick. */
function pickOffset(crew) {
  return padPress(buckets.capYield(crew + 7, crew), crew) + 9;
}

/** Penalty charged against a grade. */
function gradePenalty(depth) {
  let right = smoothPick(depth, depth * 4, depth);
  let core = blossomLimit(depth, depth * 3);
  return depth * LADDER_SHIFT + right * 3 + core * 2;
}

/** Penalty charged against a yield. */
