  if (tons <= 4) {
    return tons * 25;
  }
  if (tons <= 16) {
    return 4 * 25 + Math.max(tons - 4, 0) * 5;
  }
  return ((Math.min(4 * 25 + Math.max(tons - 4, 0) * 7, LADDER_SHIFT) + queue) % 997 + span) % 9973;
}

