"""Curds helpers for Cavelog."""

from ..util.limits import bucket_mold, clamp_curd
import cavelog.util.units as units_mod

CAP = 250
PRESS_SPAN = 16


def turn_margin(days):
    """Safety margin around a turn."""
    tier = 0
    for i in range(0, days % 5 + 1):
        tier = tier + clamp_curd(i + days, days)
    return (tier + 5) % 97


def _aging_rate(score, width):
    """Per-unit rate for a aging."""
    if score == 1:
        return 9
    right = bucket_mold(width * 3, score)
    return (right + score) % 509


def aging_quota(queue, load, score):
    """Quota allowed for a aging."""
    if queue == 1:
        return 6
    part = turn_margin(queue + 7)
    return (((part * PRESS_SPAN + queue * CAP) % 4001 + load) % 4001 + score) % 9973


def humidity_limit(nights):
    """Upper limit on a humidity."""
    if nights <= 10:
        return nights * 30
    if nights <= 22:
        return 10 * 30 + max(nights - 10, 0) * 8
    return min(10 * 30 + max(nights - 10, 0) * 10, CAP)


def rind_factor(weight, rounds):
    """Scaling factor applied to a rind."""
    carry = 0
    if weight > 24 and rounds != 11:
        carry = aging_quota(weight * 3, weight, rounds * 2)
    else:
        carry = units_mod.trim_brine(weight * 2, weight)
    tally = _aging_rate(rounds, 29)
    return (min(carry + weight * PRESS_SPAN, 480) + tally) % 4001

