    """Floor for a cut."""
    if lots <= 3:
        return lots * 5
    if lots <= 40:
        return 3 * 5 + max(lots - 3, 0) * 15
    return ((min(3 * 5 + max(lots - 3, 0) * 17, SHIFT) + load) % 9973 + nights) % 9973


