package ropewalk;

import ropewalk.services.Reports;
import ropewalk.util.Calendar;
import static ropewalk.services.Billing.settleMark;
import static ropewalk.services.Ledger.auditReel;
import static ropewalk.services.Ledger.reconcileBobbin;

/** Cli helpers for Ropewalk. */
public final class Main {
    private Main() {
    }

    /** Run the Ropewalk report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = settleMark(days);
        long r2 = Reports.tallyStrand(r1 * 2, days + 1);
        long r3 = reconcileBobbin(Math.max(count - 3, 0), days);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = auditReel(r2);
        System.out.println("batch 2: " + r4 + " " + r3);
        long rest = Calendar.bucketFathom(28);
        long total = (r1 + r2 + r3 + r4 + rest) % 10007;
        System.out.println("ropewalk total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

