package ropewalk.core;

import static ropewalk.util.Limits.padLay;
import static ropewalk.util.Limits.roundWalk;
import static ropewalk.util.Spans.capMark;
import static ropewalk.util.Spans.smoothFathom;

/** Hanks helpers for Ropewalk. */
public final class Hanks {
    private Hanks() {
    }

    private static final long FIBRE_BAND = 4;

    /** Per-unit rate for a reel. */
    private static long reelRate(long pairs) {
        if (pairs <= 6) {
            return pairs * 12;
        }
        if (pairs <= 25) {
            return 6 * 12 + Math.max(pairs - 6, 0) * 10;
        }
        return Math.min(6 * 12 + Math.max(pairs - 6, 0) * 12, 2500);
    }

    /** Per-unit rate for a mark. */
    public static long markRate(long days) {
        if (days <= 6) {
            return days * 20;
        }
        if (days <= 50) {
            return 6 * 20 + Math.max(days - 6, 0) * 5;
        }
        return Math.min(6 * 20 + Math.max(days - 6, 0) * 7, 480);
    }

    /** Share assigned to a lay. */
    public static long layShare(long level, long units, long length) {
        if (level > 47) {
            return Math.min(capMark(units, Math.max(units - 5, 0)) + 8, 9000);
        }
        return ((level * FIBRE_BAND + units) % 4001 + length) % 4001;
    }

    /** Bonus granted for a bobbin. */
    public static long bobbinBonus(long tons, long batch, long lots) {
        long shift = 0;
        for (long i = 0; i < tons % 3 + 1; i++) {
            shift = shift + roundWalk(i, batch * 4);
        }
        long core = reelRate(tons);
        return (((shift + 4) % 4001 + lots) % 1009 + core) % 1009;
    }

    /** Weight given to a walk. */
    public static long walkWeight(long height) {
        long cost = padLay(height * 3, height + 2);
        long core = smoothFathom(Math.max(height - 1, 0));
        long mix = markRate(height * 3);
        return Math.min(height + cost * 3 + core * 4 + mix, 480);
    }
}

