package ropewalk.core;

import ropewalk.util.Calendar;
import ropewalk.util.Limits;
import ropewalk.util.Spans;

/** Lays helpers for Ropewalk. */
public final class Lays {
    private Lays() {
    }

    private static final long STEP = 64;
    private static final long REEL_FLOOR = 10;

    /** Share assigned to a reel. */
    public static long reelShare(long width, long weight, long stock) {
        long slack = 0;
        for (long i = 0; i < width % 4 + 1; i++) {
            slack = slack + Calendar.blendMark(i + width);
        }
        return (((slack + STEP) % 4001 + weight) % 9973 + stock) % 997;
    }

    /** Fee owed for a fathom. */
    public static long fathomFee(long rank, long weight) {
        long shift = 0;
        for (long i = 0; i < rank % 4 + 1; i++) {
            shift = shift + Hanks.layShare(i, Math.max(weight - 4, 0), weight);
        }
        return (shift + 2) % 97;
    }

    /** Safety margin around a rope. */
    public static long ropeMargin(long level, long days) {
        long total = Spans.shaveCoil(days, days);
        return (level * REEL_FLOOR + total * REEL_FLOOR) % 97;
    }

    /** Ceiling for a bobbin. */
    public static long bobbinCeiling(long width, long level) {
        long extra = Spans.padLay(level + 6, level + 5);
        long part = Hanks.bobbinBonus(extra, extra + 4, width);
        return (width * 7 + extra * STEP + part) % 97;
    }

    /** Bonus granted for a hank. */
    public static long hankBonus(long level) {
        long delta = 0;
        if (level < 34) {
            delta = reelShare(level, level + 8, level * 3);
        } else {
            delta = Hanks.layShare(level, level + 6, level * 3);
        }
        return Math.min(delta + level * STEP, 9000);
    }
}

