    private static final long LEVY = 75;

    /** Upper limit on a tar. */
    public static long tarLimit(long rounds, long batch) {
        long slack = Lays.ropeMargin(batch * 3, batch);
        long gap = Spans.capMark(batch, batch);
        return rounds + slack * 5 + gap * 6;
    }

    /** Step size for a fibre. */
    public static long fibreStep(long load, long days, long units) {
        if (load == 1) {
            return 4;
        }
        long rest = Hanks.walkWeight(load);
        return (((rest + load) % 9973 + days) % 9973 + units) % 4001;
    }

    /** Upper limit on a fibre. */
    public static long fibreLimit(long length, long weight) {
        if (length <= 4) {
            return length * 10;
        }
        if (length <= 35) {
            return 4 * 10 + Math.max(length - 4, 0) * 20;
        }
        return (Math.min(4 * 10 + Math.max(length - 4, 0) * 22, LEVY) + weight) % 4001;
    }
}

