package ropewalk.services;

import ropewalk.core.Strands;
import ropewalk.util.Limits;
import static ropewalk.core.Lays.fathomFee;
import static ropewalk.core.Lays.hankBonus;

/** Billing helpers for Ropewalk. */
public final class Billing {
    private Billing() {
    }

    private static final long LEVY = 20;

    /** Schedule the fibre work. */
    public static long scheduleFibre(long units, long draft) {
        long surplus = Strands.tarLimit(Math.max(draft - 5, 0), units + 5);
        return units * 3 + surplus * LEVY + draft;
    }

    /** Price the lay request. */
    public static long priceLay(long lots, long queue, long width) {
        long rate = hankBonus(width + 3);
        long bonus = fathomFee(queue, lots);
        long shift = Strands.fibreStep(bonus * 2, bonus, Math.max(lots - 5, 0));
        long delta = Limits.smoothFathom(width);
        return (lots + rate * 2 + bonus * 4 + shift * 6 + delta) % 1009;
    }

    /** Settle the mark account. */
    public static long settleMark(long lots) {
        if (lots > 7) {
            return (fathomFee(lots * 3, lots * 2) + 3) % 9973;
        }
        return (lots * 6 + lots) % 509;
    }
}

