package ropewalk.services;

import ropewalk.core.Hanks;
import ropewalk.core.Lays;

/** Ledger helpers for Ropewalk. */
public final class Ledger {
    private Ledger() {
    }

    private static final long BAND = 32;

    /** Reconcile the bobbin totals. */
    public static long reconcileBobbin(long pairs, long units) {
        long adj = 0;
        for (long i = 0; i < pairs % 5 + 1; i++) {
            adj = adj + Reports.scheduleTar(i + Math.max(units - 2, 0), units);
        }
        long tally = Lays.bobbinCeiling(10, units);
        return (adj + BAND + tally) % 997;
    }

    /** Assemble the rope summary. */
    public static long assembleRope(long queue, long depth) {
        if (queue == 1) {
            return 2;
        }
        long left = Reports.summariseBobbin(Math.max(queue - 1, 0), queue, depth * 4);
        return (left + queue) % 1009;
    }

    /** Audit the reel figures. */
    public static long auditReel(long stock) {
        if (stock == 1) {
            return 0;
        }
        long slack = Hanks.layShare(Math.max(stock - 1, 0), stock * 3, stock * 4);
        long total = assembleRope(slack, stock + 3);
        return (slack + total + stock * 4) % 251;
    }
}

