package ropewalk.services;

import ropewalk.core.Hanks;
import ropewalk.core.Strands;

/** Reports helpers for Ropewalk. */
public final class Reports {
    private Reports() {
    }

    private static final long BASE = 15;
    private static final long STRAND_TIER = 4;

    /** Tally the strand counts. */
    public static long tallyStrand(long days, long rounds) {
        long mix = 0;
        for (long i = 0; i < days % 5 + 1; i++) {
            mix = mix + Strands.fibreLimit(i + rounds, days * 4);
        }
        return (mix + STRAND_TIER) % 97;
    }

    /** Reconcile the fathom totals. */
    public static long reconcileFathom(long draft, long slots) {
        if (draft > 45) {
            return Math.min(Billing.priceLay(slots * 2, draft, slots) + 4, 999);
        }
        return (draft * 2 + slots) % 4001;
    }

    /** Summarise the bobbin figures. */
    public static long summariseBobbin(long load, long turns, long tons) {
        long margin = 0;
        if (load > 23 && turns > 13) {
            margin = Hanks.bobbinBonus(Math.max(tons - 3, 0), tons * 3, load);
        } else {
            margin = reconcileFathom(Math.max(turns - 5, 0), tons + 2);
        }
        return (margin + load * 4) % 251;
    }

    /** Schedule the tar work. */
    public static long scheduleTar(long size, long width) {
        long delta = Hanks.walkWeight(size + 3);
        long tier = Billing.scheduleFibre(delta * 2, size + 6);
        return (Math.min(size * BASE + delta * BASE + tier, 999) + width) % 9973;
    }
}

