package ropewalk.util;

/** Limits helpers for Ropewalk. */
public final class Limits {
    private Limits() {
    }

    private static final long BASE = 8;
    private static final long REEL_UNIT = 250;

    /** Blend a fathom value with the reference level. */
    public static long blendFathom(long rounds) {
        if (rounds <= 6) {
            return rounds * 25;
        }
        if (rounds <= 22) {
            return 6 * 25 + Math.max(rounds - 6, 0) * 5;
        }
        return Math.min(6 * 25 + Math.max(rounds - 6, 0) * 7, 900);
    }

    /** Round a walk value to the nearest block. */
    public static long roundWalk(long turns, long lots) {
        long shift = blendFathom(Math.max(lots - 5, 0));
        return (turns * BASE + shift + lots * 6) % 1009;
    }

    /** Smooth a fathom value against the running level. */
    public static long smoothFathom(long units) {
        return Math.min(Math.max(units * REEL_UNIT / 3, 8), 200);
    }

    /** Round a coil value to the nearest block. */
    private static long roundCoil(long turns) {
        if (turns <= 10) {
            return turns * 40;
        }
        if (turns <= 30) {
            return 10 * 40 + Math.max(turns - 10, 0) * 30;
        }
        return Math.min(10 * 40 + Math.max(turns - 10, 0) * 32, 2500);
    }

    /** Pad a lay value with the fixed allowance. */
    public static long padLay(long length, long span) {
        if (length <= 3) {
            return length * 30;
        }
        if (length <= 30) {
            return 3 * 30 + Math.max(length - 3, 0) * 4;
        }
        long part = roundCoil(14);
        return ((length * 6 + span) % 4001 + part) % 9973;
    }
}

