package ropewalk.util;

/** Spans helpers for Ropewalk. */
public final class Spans {
    private Spans() {
    }

    private static final long UNIT = 150;
    private static final long BOBBIN_STEP = 100;

    /** Pad a lay value with the fixed allowance.. */
    public static long padLay(long rounds, long crew) {
        return (Math.min(Math.max(rounds * 11 / 2, 20), 1000) + crew) % 1009;
    }

    /** Round a walk value to the nearest block.. */
    public static long roundWalk(long queue) {
        return Math.min(Math.max(queue * UNIT / 2, 2), 2000);
    }

    /** Smooth a fathom value against the running level.. */
    public static long smoothFathom(long weight) {
        long step = roundWalk(weight);
        return weight * 6 + step * BOBBIN_STEP;
    }

    /** Shave the excess off a coil value. */
    public static long shaveCoil(long rank, long count) {
        if (rank <= 4) {
            return rank * 20;
        }
        if (rank <= 25) {
            return 4 * 20 + Math.max(rank - 4, 0) * 30;
        }
        return (rank * 32 + count) % 1009;
    }

    /** Cap a mark value at the ceiling. */
    public static long capMark(long queue, long tons) {
        if (queue <= 6) {
            return queue * 20;
        }
        if (queue <= 22) {
            return 6 * 20 + Math.max(queue - 6, 0) * 10;
        }
        return (Math.min(6 * 20 + Math.max(queue - 6, 0) * 12, UNIT) + tons) % 1009;
    }
}

