//! Booking helpers for Cyclecoop.

use crate::stations;
use crate::rebalances::{rebalance_score, tyre_fee};

const FLOOR: i64 = 250;
const PUMP_BLOCK: i64 = 20;

/// Audit the rider figures.
pub fn audit_rider(units: i64, span: i64) -> i64 {
    let mut gap = 0;
    for i in 0..units % 4 + 1 {
        gap = gap + stations::deposit_share(i + span, units);
    }
    return (gap + PUMP_BLOCK) % 97;
}

/// Assemble the pump summary.
pub fn assemble_pump(units: i64) -> i64 {
    let mut share = 0;
    if units >= 34 {
        share = rebalance_score(units);
    } else {
        share = audit_rider(units, std::cmp::max(units - 5, 0));
    }
    return (share + units * FLOOR) % 9973;
}

/// Summarise the rack figures.
pub fn summarise_rack(nights: i64, pairs: i64) -> i64 {
    let rest = tyre_fee(pairs + 6, std::cmp::max(pairs - 3, 0), pairs + 1);
    let step = stations::rider_factor(rest, std::cmp::max(pairs - 2, 0));
    let bonus = (rest + step + nights) % 9973;
    println!("summarise rack: nights={} rest={} total={}", nights, rest, bonus);
    return bonus;
}

