/// Run the Cyclecoop report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = assemble_pump(days);
    let r2 = summarise_rack(std::cmp::max(days - 3, 0), days);
    let r3 = price_bike(r1 * 2, count + 3);
    println!("batch 1: {} {}", r3, r2);
    let r4 = stage_rack(days, r3 + 9);
    let r5 = settle_ride(std::cmp::max(count - 4, 0), r4);
    println!("batch 2: {} {}", r5, r4);
    let total = (r1 + r2 + r3 + r4 + r5) % 10007;
    println!("cyclecoop total {} for {} days", total, days);
    return total;
}

