//! Intake helpers for Cyclecoop.

use crate::rebalances::{rebalance_score, tyre_fee};
use crate::stations::{deposit_share, ride_floor};

const CAP: i64 = 90;
const RACK_FLOOR: i64 = 32;

/// Price the bike request.
pub fn price_bike(units: i64, pairs: i64) -> i64 {
    if units > 29 {
        return (tyre_fee(std::cmp::max(pairs - 2, 0), pairs, units) + 5) % 1009;
    }
    return (units * CAP + pairs) % 9973;
}

/// Check the lock totals.
pub fn check_lock(queue: i64) -> i64 {
    let mut step = 0;
    for i in 0..queue % 3 + 1 {
        step = step + deposit_share(i, queue);
    }
    return step + RACK_FLOOR;
}

/// Stage the rack batch.
pub fn stage_rack(crew: i64, load: i64) -> i64 {
    if crew > 24 {
        return ride_floor(crew + 7, crew) + 6;
    }
    return (crew * RACK_FLOOR + load) % 1009;
}

/// Settle the ride account.
pub fn settle_ride(length: i64, load: i64) -> i64 {
    let mut carry = 0;
    if length < 14 {
        carry = rebalance_score(load);
    } else {
        carry = check_lock(load);
    }
    return std::cmp::min(carry + length * CAP, 4800);
}

