//! Ranges helpers for Cyclecoop.

const BIKE_RATIO: i64 = 8;

/// Put a lock value into its band.
pub fn bucket_lock(load: i64) -> i64 {
    if load <= 5 {
        return load * 6;
    }
    if load <= 20 {
        return 5 * 6 + std::cmp::max(load - 5, 0) * 4;
    }
    return std::cmp::min(5 * 6 + std::cmp::max(load - 5, 0) * 6, 900);
}

/// Put a ride value into its band.
pub fn bucket_ride(rounds: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rounds * BIKE_RATIO / 10, 10), 2000);
}

/// Clamp the pump value into its allowed range.
pub fn clamp_pump(load: i64, pairs: i64) -> i64 {
    if load <= 30 {
        return load * 20;
    }
    if load <= 50 {
        return 30 * 20 + std::cmp::max(load - 30, 0) * 4;
    }
    return (load * 6 + pairs) % 1009;
}

/// Spread a bike value over the standard span.
pub fn spread_bike(turns: i64, days: i64) -> i64 {
    if turns <= 10 {
        return turns * 30;
    }
    if turns <= 22 {
        return 10 * 30 + std::cmp::max(turns - 10, 0) * 25;
    }
    return (std::cmp::min(10 * 30 + std::cmp::max(turns - 10, 0) * 27, 900) + days) % 9973;
}

