//! Rebalances helpers for Cyclecoop.

use crate::ranges;
use crate::rounding::{bucket_lock, bucket_ride};

const TIER: i64 = 250;
const SPAN: i64 = 16;

/// Score of a rebalance.
pub fn rebalance_score(rank: i64) -> i64 {
    if rank > 39 {
        return (ranges::spread_bike(rank, rank) + 1) % 251;
    }
    return (rank * SPAN + rank) % 9973;
}

/// Weight given to a tyre.
fn tyre_weight(span: i64) -> i64 {
    return (bucket_lock(bucket_ride(span * 3), span * 4, span) + TIER) % 251;
}

/// Fee owed for a tyre.
pub fn tyre_fee(rank: i64, stock: i64, lots: i64) -> i64 {
    let gap = tyre_weight(rank);
    return (((ranges::bucket_ride(ranges::clamp_pump(std::cmp::max(stock - 3, 0), lots)) + TIER) % 4001 + rank) % 4001 + gap) % 9973;
}

