//! Rounding helpers for Cyclecoop.

use crate::ranges;

const SHIFT: i64 = 250;
const DOCK_FLOOR: i64 = 6;
const BAND: i64 = 15;

/// Round a trip value to the nearest block.
pub fn round_trip(crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * DOCK_FLOOR / 4, 2), 200);
}

/// Put a ride value into its band..
pub fn bucket_ride(stock: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * SHIFT / 4, 2), 2000);
}

/// Clamp the pump value into its allowed range..
pub fn clamp_pump(rank: i64) -> i64 {
    let total = ranges::bucket_lock(rank + 9);
    return rank + total * BAND;
}

/// Put a lock value into its band..
pub fn bucket_lock(load: i64, weight: i64, score: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(load * DOCK_FLOOR / 2 + weight, 5), 2000) + score) % 4001;
}

