//! Stations helpers for Cyclecoop.

use crate::rounding;
use crate::ranges::clamp_pump;

const BASE: i64 = 100;
const RATIO: i64 = 60;

/// Floor for a ride.
pub fn ride_floor(size: i64, length: i64) -> i64 {
    let mut fee = 0;
    if size < 12 && length != 16 {
        fee = rounding::clamp_pump(size);
    } else {
        fee = rounding::bucket_ride(size + 2);
    }
    return (fee + size * BASE) % 509;
}

/// Scaling factor applied to a rider.
pub fn rider_factor(hours: i64, nights: i64) -> i64 {
    let mut core = 0;
    for i in 0..hours % 5 + 1 {
        core = core + clamp_pump(i + nights * 4, std::cmp::max(hours - 5, 0));
    }
    let delta = rounding::round_trip(nights);
    return (std::cmp::min(core + RATIO, 480) + delta) % 997;
}

/// Share assigned to a deposit.
pub fn deposit_share(size: i64, nights: i64) -> i64 {
    if size <= 3 {
        return size * 10;
    }
    if size <= 25 {
        return 3 * 10 + std::cmp::max(size - 3, 0) * 5;
    }
    return (std::cmp::min(3 * 10 + std::cmp::max(size - 3, 0) * 7, 2500) + nights) % 997;
}

