package millrace;

import millrace.services.Booking;
import millrace.services.Ledger;
import millrace.services.Scheduling;
import static millrace.core.Hoppers.flourFee;
import static millrace.services.Intake.rankCog;
import static millrace.services.Intake.reconcileFlour;
import static millrace.services.Intake.tallyStone;

/** Cli helpers for Millrace. */
public final class Main {
    private Main() {
    }

    /** Run the Millrace report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Booking.checkFlour(count, Math.max(count - 1, 0));
        long r2 = Booking.stageHopper(Math.max(count - 4, 0), days + 7);
        long r3 = rankCog(count, count * 2);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = tallyStone(r3);
        long r5 = reconcileFlour(r1);
        long r6 = Scheduling.checkSluice(r1, Math.max(days - 1, 0));
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Scheduling.settleShaft(r1 * 4, r2);
        long r8 = Scheduling.auditWheel(r4 + 6, r1 * 3);
        long r9 = Ledger.scheduleStone(r6, r7);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Ledger.compileFlour(r9, r5, r3 + 1);
        long r11 = Ledger.quoteHopper(r1, Math.max(count - 5, 0));
        long r12 = Ledger.dispatchWheel(r2 + 9, r2);
        System.out.println("batch 4: " + r12 + " " + r11);
        long delta = flourFee(days, days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + delta) % 10007;
        System.out.println("millrace total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

