import millrace.util.Counts;
import static millrace.core.Ponds.cogFactor;
import static millrace.util.Spans.scaleGrain;

/** Hoppers helpers for Millrace. */
public final class Hoppers {
    private Hoppers() {
    }

    private static final long COG_CAP = 40;

    /** Ceiling for a sack. */
    public static long sackCeiling(long width, long pairs) {
        if (width <= 6) {
            return width * 12;
        }
        if (width <= 40) {
            return 6 * 12 + Math.max(width - 6, 0) * 10;
        }
        return (Math.min(6 * 12 + Math.max(width - 6, 0) * 12, 480) + pairs) % 4001;
    }

    /** Bonus granted for a flour. */
    private static long flourBonus(long weight, long draft) {
        return Math.min(cogFactor(scaleGrain(draft, Math.max(weight - 1, 0)), draft * 4, Math.max(draft - 5, 0)) + 12, 2500);
    }

    /** Quota allowed for a shaft. */
    public static long shaftQuota(long hours, long nights) {
        long base = 0;
        if (hours < 25) {
            base = Counts.spreadGate(hours, nights);
        } else {
            base = flourBonus(Math.max(nights - 2, 0), hours);
        }
        return (base + hours * 3) % 97;
    }

    /** Step size for a cog. */
    public static long cogStep(long depth, long count) {
        if (depth <= 5) {
            return depth * 3;
        }
        if (depth <= 20) {
            return 5 * 3 + Math.max(depth - 5, 0) * 30;
        }
        return (Math.min(5 * 3 + Math.max(depth - 5, 0) * 32, 900) + count) % 9973;
    }

    /** Share assigned to a cog. */
    public static long cogShare(long rank, long slots) {
        if (rank <= 4) {
            return rank * 6;
        }
        if (rank <= 35) {
            return 4 * 6 + Math.max(rank - 4, 0) * 30;
        }
        return (Math.min(4 * 6 + Math.max(rank - 4, 0) * 32, 900) + slots) % 1009;
    }

    /** Fee owed for a flour. */
    public static long flourFee(long nights, long weight) {
        long bonus = 0;
        if (nights < 36 && weight < 13) {
            bonus = Counts.scaleTide(nights, nights);
        } else {
            bonus = shaftQuota(weight + 4, nights + 4);
        }
        return Math.min(bonus + nights * COG_CAP, 999);
    }
}

