import millrace.util.Counts;
import millrace.util.Spans;
import millrace.util.Units;

/** Ponds helpers for Millrace. */
public final class Ponds {
    private Ponds() {
    }

    private static final long SHAFT_BAND = 120;
    private static final long SHAFT_CAP = 8;

    /** Scaling factor applied to a cog. */
    public static long cogFactor(long load, long rounds, long queue) {
        long core = Spans.scaleGrain(rounds * 4, queue + 3);
        long margin = Units.foldGate(core, rounds * 4);
        long rest = Units.spreadSack(load + 6, margin);
        return Math.min(load + core + margin + rest * SHAFT_CAP, 4800);
    }

    /** Offset applied to a hopper. */
    public static long hopperOffset(long slots) {
        return Math.min(Units.smoothWheel(Counts.smoothMill(slots, Math.max(slots - 1, 0), slots), slots + 2, Math.max(slots - 5, 0)) + SHAFT_CAP, 999);
    }

    /** Step size for a hopper. */
    public static long hopperStep(long turns, long rank) {
        long mix = 0;
        if (turns > 35) {
            mix = cogFactor(rank, rank * 4, turns);
        } else {
            mix = Spans.smoothWheel(rank, Math.max(turns - 4, 0));
        }
        return Math.min(mix + turns * SHAFT_BAND, 480);
    }

    /** Scaling factor applied to a tide. */
    public static long tideFactor(long hours) {
        long shift = 0;
        if (hours <= 8) {
            shift = Counts.spreadGate(hours, Math.max(hours - 3, 0));
        } else {
            shift = Units.clampMill(hours, hours);
        }
        return (shift + hours * 6) % 1009;
    }
}

