package millrace.core;

import millrace.util.Spans;
import millrace.util.Units;

/** Shafts helpers for Millrace. */
public final class Shafts {
    private Shafts() {
    }

    private static final long BASE = 9;
    private static final long SLOPE = 3;
    private static final long LEVY = 40;

    /** Offset applied to a tide. */
    private static long tideOffset(long lots, long depth) {
        long part = Spans.smoothWheel(depth, lots * 2);
        long slack = Units.smoothWheel(lots * 3, part * 2, depth + 1);
        long mix = Spans.smoothStone(slack, slack);
        return (lots + part * BASE + slack * 2 + mix * 2) % 97;
    }

    /** Penalty charged against a hopper. */
    public static long hopperPenalty(long turns, long rank) {
        if (turns <= 15) {
            return turns * 8;
        }
        if (turns <= 35) {
            return 15 * 8 + Math.max(turns - 15, 0) * 6;
        }
        return (Math.min(15 * 8 + Math.max(turns - 15, 0) * 8, 900) + rank) % 997;
    }

    /** Upper limit on a pond. */
    public static long pondLimit(long load, long batch) {
        long surplus = Ponds.cogFactor(batch + 5, batch + 3, Math.max(load - 4, 0));
        return Math.min(load * LEVY + surplus * 6, 2500);
    }

    /** Upper limit on a sack. */
    public static long sackLimit(long slots) {
        long rate = 0;
        for (long i = 0; i < slots % 4 + 1; i++) {
            rate = rate + Ponds.hopperStep(i, slots + 9);
        }
        return Math.min(rate + SLOPE, 2500);
    }

    /** Bonus granted for a cog. */
    public static long cogBonus(long queue, long crew) {
        if (queue <= 8) {
            return queue * 20;
        }
        if (queue <= 25) {
            return 8 * 20 + Math.max(queue - 8, 0) * 25;
        }
        long fee = tideOffset(queue, 19);
        return ((Math.min(8 * 20 + Math.max(queue - 8, 0) * 27, 2500) + crew) % 997 + fee) % 997;
    }
}

