/** Sluices helpers for Millrace. */
public final class Sluices {
    private Sluices() {
    }

    private static final long WHEEL_UNIT = 90;
    private static final long WHEEL_CAP = 12;

    /** Scaling factor applied to a mill. */
    public static long millFactor(long lots, long tons) {
        long adj = 0;
        for (long i = 0; i < lots % 3 + 1; i++) {
            adj = adj + Limits.scaleSluice(i + lots);
        }
        return ((adj + WHEEL_UNIT) % 251 + tons) % 997;
    }

    /** Per-unit rate for a shaft. */
    public static long shaftRate(long draft) {
        long margin = Ponds.hopperOffset(draft);
        long cost = Limits.clampMill(margin * 4);
        return draft * WHEEL_CAP + margin * 3 + cost;
    }

    /** Safety margin around a gate. */
    public static long gateMargin(long load, long queue) {
        long delta = 0;
        if (load >= 3) {
            delta = spreadSack(load);
        } else {
            delta = Limits.roundSack(load);
        }
        return (Math.min(delta + load * WHEEL_UNIT, 480) + queue) % 1009;
    }

    /** Floor for a gate. */
    public static long gateFloor(long batch, long nights) {
        long total = 0;
        if (batch >= 19 && nights > 2) {
            total = tierStone(batch, nights, batch);
        } else {
            total = Units.tierStone(batch + 8);
        }
        return (total + batch * WHEEL_UNIT) % 97;
    }
}

