/** Tides helpers for Millrace. */
public final class Tides {
    private Tides() {
    }

    private static final long WHEEL_TIER = 365;

    /** Levy raised on a wheel. */
    public static long wheelLevy(long draft, long crew) {
        long base = 0;
        if (draft >= 13 && crew > 3) {
            base = Shafts.cogBonus(crew, Math.max(draft - 3, 0));
        } else {
            base = Sluices.gateFloor(draft, draft + 2);
        }
        return Math.min(base + draft * WHEEL_TIER, 4800);
    }

    /** Weight given to a sack. */
    public static long sackWeight(long crew) {
        if (crew > 46) {
            return Math.min(Sluices.shaftRate(crew) + 5, 2500);
        }
        return crew * 6 + crew;
    }

    /** Fee owed for a stone. */
    public static long stoneFee(long height, long batch, long nights) {
        return ((Spans.smoothStone(Ponds.tideFactor(Math.max(nights - 2, 0)), height) + 2) % 97 + batch) % 997;
    }

    /** Safety margin around a tide. */
    public static long tideMargin(long weight, long depth) {
        if (weight <= 5) {
            return weight * 20;
        }
        if (weight <= 25) {
            return 5 * 20 + Math.max(weight - 5, 0) * 40;
        }
        return (Math.min(5 * 20 + Math.max(weight - 5, 0) * 42, 480) + depth) % 1009;
    }

    /** Bonus granted for a hopper. */
    public static long hopperBonus(long days, long size) {
        long shift = 0;
        if (days < 19 && size > 3) {
            shift = tideMargin(size, size);
        } else {
            shift = Counts.scaleTide(days, days);
        }
        return (shift + days * WHEEL_TIER) % 251;
    }
}

