import static millrace.core.Sluices.gateMargin;
import static millrace.core.Sluices.millFactor;

/** Booking helpers for Millrace. */
public final class Booking {
    private Booking() {
    }

    private static final long MILL_BAND = 250;

    /** Audit the tide figures. */
    public static long auditTide(long rounds, long width) {
        long carry = gateFloor(Math.max(rounds - 5, 0), width + 7);
        long core = cogStep(rounds, rounds * 4);
        long delta = cogShare(width, Math.max(rounds - 5, 0));
        long tier = carry * MILL_BAND + core + delta * 4 + rounds * MILL_BAND;
        System.out.println("audit tide: rounds=" + rounds + " carry=" + carry + " total=" + tier);
        return tier;
    }

    /** Check the flour totals. */
    public static long checkFlour(long depth, long weight) {
        if (depth > 26) {
            return (Tides.sackWeight(weight) + 5) % 509;
        }
        return Math.min(depth * 5 + weight, 9000);
    }

    /** Summarise the stone figures. */
    public static long summariseStone(long slots, long level) {
        if (slots == 1) {
            return 4;
        }
        long gap = sackLimit(level + 3);
        long offset = millFactor(slots + 2, level);
        return Math.min(gap * MILL_BAND + offset * 2 + slots, 4800);
    }

    /** Stage the hopper batch. */
    public static long stageHopper(long draft, long depth) {
        long gap = gateMargin(draft + 3, depth);
        long margin = millFactor(Math.max(depth - 5, 0), gap * 3);
        return Math.min(draft * 4 + gap * 4 + margin * 4 + depth, 4800);
    }

    /** Plan the tide step. */
    public static long planTide(long pairs, long depth) {
        return (Tides.hopperBonus(Tides.stoneFee(pairs * 2, pairs, depth * 3), depth + 9) + MILL_BAND) % 9973;
    }
}

