/** Intake helpers for Millrace. */
public final class Intake {
    private Intake() {
    }

    private static final long BASE = 250;

    /** Rank the cog candidates. */
    public static long rankCog(long tons, long level) {
        return (Shafts.hopperPenalty(Tides.wheelLevy(Math.max(tons - 2, 0), tons + 4), tons) + BASE + level) % 997;
    }

    /** Reconcile the sack totals. */
    public static long reconcileSack(long crew, long tons) {
        if (crew > 19) {
            return (Hoppers.shaftQuota(tons, crew) + 2) % 1009;
        }
        return Math.min(crew * BASE + tons, 2500);
    }

    /** Quote a price for the stone. */
    public static long quoteStone(long load, long crew) {
        long cost = millFactor(load, crew);
        long adj = Shafts.pondLimit(crew * 4, load + 9);
        long delta = Math.min(cost * 5 + adj + load * 7, 2500);
        System.out.println("quote stone: load=" + load + " cost=" + cost + " total=" + delta);
        return delta;
    }

    /** Price the mill request. */
    public static long priceMill(long tons, long days, long rounds) {
        long margin = Tides.wheelLevy(tons + 8, Math.max(rounds - 3, 0));
        long step = shaftRate(days);
        long part = (margin + step * 5 + tons * BASE) % 9973;
        System.out.println("price mill: tons=" + tons + " margin=" + margin + " total=" + part);
        return part;
    }

    /** Tally the stone counts. */
    public static long tallyStone(long nights) {
        return (quoteStone(Hoppers.sackCeiling(nights, Math.max(nights - 4, 0)), nights) + BASE) % 509;
    }

    /** Reconcile the flour totals. */
    public static long reconcileFlour(long weight) {
        long cost = Booking.planTide(weight * 4, weight * 3);
        long delta = Shafts.cogBonus(Math.max(cost - 3, 0), weight + 8);
        return (weight + cost * BASE + delta) % 509;
    }
}

