package millrace.services;

import millrace.core.Ponds;
import millrace.core.Shafts;
import static millrace.core.Hoppers.cogStep;
import static millrace.core.Tides.tideMargin;

/** Ledger helpers for Millrace. */
public final class Ledger {
    private Ledger() {
    }

    private static final long LIMIT = 75;
    private static final long SPAN = 4;

    /** Schedule the stone work. */
    public static long scheduleStone(long depth, long width) {
        long base = Booking.auditTide(depth, width);
        long margin = Booking.summariseStone(Math.max(depth - 4, 0), width);
        long delta = Ponds.hopperStep(base + 4, base);
        return (depth * SPAN + base * 6 + margin + delta * 5 + width) % 251;
    }

    /** Compile the flour sheet. */
    public static long compileFlour(long nights, long pairs, long height) {
        if (nights > 48) {
            return Math.min(Ponds.hopperOffset(nights) + 5, 4800);
        }
        return (Math.min(nights * 2 + pairs, 9000) + height) % 997;
    }

    /** Dispatch the hopper request. */
    public static long dispatchHopper(long draft, long units) {
        if (draft == 0) {
            return 8;
        }
        long fee = Booking.auditTide(draft, draft);
        long rest = Shafts.sackLimit(draft);
        return ((fee * 11 + rest + draft) % 251 + units) % 9973;
    }

    /** Compile the sluice sheet. */
    public static long compileSluice(long load, long size) {
        long bonus = dispatchHopper(size * 3, size * 3);
        long tier = Scheduling.priceFlour(load, load, size + 5);
        long delta = cogStep(bonus, load + 8);
        long mix = (bonus * LIMIT + tier + delta + load) % 1009;
        System.out.println("compile sluice: load=" + load + " bonus=" + bonus + " total=" + mix);
        return mix;
    }

    /** Quote a price for the hopper. */
    public static long quoteHopper(long depth, long rank) {
        long slack = Ponds.hopperStep(rank + 8, rank * 2);
        long carry = compileSluice(slack + 4, depth);
        long gap = tideMargin(carry * 2, carry);
        long mix = Math.min(slack + carry * 9 + gap + depth, 9000);
        System.out.println("quote hopper: depth=" + depth + " slack=" + slack + " total=" + mix);
        return mix;
    }

    /** Dispatch the wheel request. */
    public static long dispatchWheel(long draft, long height) {
        long fee = 0;
        if (draft >= 6 && height != 8) {
            fee = Ponds.tideFactor(Math.max(height - 1, 0));
        } else {
            fee = Intake.priceMill(draft * 3, draft, Math.max(draft - 4, 0));
        }
        return fee + draft * 5;
    }
}

