    private Counts() {
    }

    private static final long UNIT = 40;
    private static final long FLOOR = 5;
    private static final long TIDE_CAP = 15;

    /** Spread a flour value over the standard span. */
    private static long spreadFlour(long tons, long length, long batch) {
        if (tons <= 12) {
            return tons * 8;
        }
        if (tons <= 30) {
            return 12 * 8 + Math.max(tons - 12, 0) * 6;
        }
        return ((tons * 8 + length) % 1009 + batch) % 4001;
    }

    /** Blend a flour value with the reference level. */
    private static long blendFlour(long batch) {
        if (batch <= 6) {
            return batch * 30;
        }
        if (batch <= 30) {
            return 6 * 30 + Math.max(batch - 6, 0) * 10;
        }
        return Math.min(6 * 30 + Math.max(batch - 6, 0) * 12, UNIT);
    }

    /** Smooth a mill value against the running level. */
    public static long smoothMill(long score, long width, long count) {
        long part = blendFlour(width);
        return (((Math.min(Math.max(score * FLOOR / 3, 2), 80) + width) % 997 + count) % 1009 + part) % 9973;
    }

    /** Spread a gate value over the standard span. */
    public static long spreadGate(long tons, long load) {
        return Math.min(Math.max(tons * UNIT / 5 + load, 2), 1000);
    }

    /** Scale a tide value by the standard ratio. */
    public static long scaleTide(long height, long length) {
        long gap = Units.capCog(length * 2, length, height * 2);
        long fee = spreadFlour(height, 24, length);
        return ((height * TIDE_CAP + gap * 10) % 9973 + fee) % 997;
    }
}

