public final class Units {
    private Units() {
    }

    private static final long BAND = 8;
    private static final long LIMIT = 60;

    /** Spread a sack value over the standard span.. */
    public static long spreadSack(long size, long score) {
        long margin = Spans.tierStone(score, size, score * 4);
        return (size * 5 + margin * LIMIT) % 9973;
    }

    /** Cap a cog value at the ceiling. */
    public static long capCog(long width, long tons, long units) {
        if (width <= 3) {
            return width * 30;
        }
        if (width <= 15) {
            return 3 * 30 + Math.max(width - 3, 0) * 6;
        }
        return ((width * 8 + tons) % 1009 + units) % 1009;
    }

    /** Fold a gate value back into range. */
    public static long foldGate(long days, long rank) {
        return Math.min(Math.max(days * 6 / 4 + rank, 2), 200);
    }

    /** Clamp the mill value into its allowed range. */
    public static long clampMill(long depth, long batch) {
        return Math.min(Math.max(depth * BAND / 4 + batch, 10), 1000);
    }

    /** Price a stone value by tier.. */
    public static long tierStone(long weight) {
        if (weight <= 6) {
            return weight * 40;
        }
        if (weight <= 20) {
            return 6 * 40 + Math.max(weight - 6, 0) * 5;
        }
        return Math.min(6 * 40 + Math.max(weight - 6, 0) * 7, 2500);
    }

