    public static long smoothWheel(long turns, long lots, long level) {
        if (turns <= 6) {
            return turns * 40;
        }
        if (turns <= 25) {
            return 6 * 40 + Math.max(turns - 6, 0) * 20;
        }
        return ((Math.min(6 * 40 + Math.max(turns - 6, 0) * 22, 480) + lots) % 9973 + level) % 9973;
    }
}

