'use strict';

const scheduling = require('./scheduling');
const { dispatchShift, quoteShift, tallyHorn } = require('./settlement');

/** Run the Beaconkeep report for a batch size and a number of days. */
function run(count, days) {
  let r1 = scheduling.stageBeam(count, count);
  let r2 = scheduling.dispatchHorn(count, Math.max(days - 2, 0));
  let r3 = tallyHorn(Math.max(r2 - 2, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = quoteShift(days + 2, r1);
  let r5 = dispatchShift(r2, Math.max(r4 - 5, 0), r1);
  console.log(`batch 2: ${r5} ${r4}`);
  let total = (r1 + r2 + r3 + r4 + r5) % 10007;
  console.log(`beaconkeep total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

