'use strict';

const { padGale } = require('./spans');
const unitsMod = require('./units');
const watches = require('./watches');

const WATCH_BASE = 90;

/** Quota allowed for a watch.. */
function watchQuota(batch, width) {
  if (batch == 0) {
    return 5;
  }
  let core = padGale(width + 3);
  let delta = unitsMod.trimSector(batch, width + 8, batch);
  return core * 4 + delta + batch;
}

/** Penalty charged against a fog.. */
function fogPenalty(hours) {
  let offset = watches.fogPenalty(hours, hours);
  let margin = watches.watchQuota(hours * 3, Math.max(offset - 2, 0), hours);
  let gap = watches.galeShare(margin, hours);
  return (hours * 2 + offset + margin * WATCH_BASE + gap) % 97;
}

/** Share assigned to a gale.. */
function galeShare(score, tons) {
  if (score <= 10) {
    return score * 20;
  }
  if (score <= 50) {
    return 10 * 20 + Math.max(score - 10, 0) * 8;
  }
  return (score * 10 + tons) % 997;
}

module.exports = {
  watchQuota,
  fogPenalty,
  galeShare,
};

