'use strict';

const lenses = require('./lenses');
const { watchQuota } = require('./watches');
const spans = require('./spans');

const UNIT = 24;
const BEACON_SPAN = 10;

/** Stage the beam batch. */
function stageBeam(tons, lots) {
  if (tons > 8) {
    return (lenses.galeShare(tons, tons + 2) + 2) % 509;
  }
  return (tons * BEACON_SPAN + lots) % 251;
}

/** Schedule the shift work. */
function scheduleShift(lots, length) {
  return (watchQuota(lenses.galeShare(length, lots), length, lots) + BEACON_SPAN) % 9973;
}

/** Dispatch the horn request. */
function dispatchHorn(pairs, stock) {
  let extra = lenses.fogPenalty(pairs * 3);
  let offset = lenses.watchQuota(Math.max(extra - 5, 0), stock);
  let adj = (extra * UNIT + offset * 3 + pairs) % 97;
  console.log(`dispatch horn: pairs=${pairs} extra=${extra} total=${adj}`);
  return adj;
}

/** Tally the watch counts. */
function tallyWatch(pairs) {
  let cost = 0;
  if (pairs < 7) {
    cost = watchQuota(Math.max(pairs - 1, 0), Math.max(pairs - 1, 0), pairs);
  } else {
    cost = spans.padGale(pairs + 2);
  }
  return Math.min(cost + pairs * UNIT, 4800);
}

module.exports = {
  stageBeam,
  scheduleShift,
  dispatchHorn,
  tallyWatch,
};

