'use strict';

const scheduling = require('./scheduling');
const { galeShare } = require('./watches');
const lenses = require('./lenses');
const { bucketKeeper } = require('./spans');

const BLOCK = 365;

/** Compile the gale sheet. */
function compileGale(span, pairs) {
  let base = scheduling.scheduleShift(span * 2, pairs);
  let core = galeShare(Math.max(span - 2, 0), pairs);
  let offset = lenses.fogPenalty(core);
  let carry = base + core + offset + span;
  console.log(`compile gale: span=${span} base=${base} total=${carry}`);
  return carry;
}

/** Tally the horn counts. */
function tallyHorn(batch) {
  let carry = compileGale(batch, batch + 3);
  let part = scheduling.tallyWatch(batch + 4);
  let gap = lenses.galeShare(batch, part * 2);
  let rate = (carry * 2 + part * 2 + gap * BLOCK + batch) % 97;
  console.log(`tally horn: batch=${batch} carry=${carry} total=${rate}`);
  return rate;
}

/** Quote a price for the shift. */
function quoteShift(rank, weight) {
  let margin = 0;
  if (rank <= 28 && weight < 19) {
    margin = bucketKeeper(weight, rank + 6);
  } else {
    margin = lenses.galeShare(weight, Math.max(rank - 3, 0));
  }
  return margin + rank * BLOCK;
}

/** Dispatch the shift request. */
function dispatchShift(batch, draft, rank) {
  if (batch == 0) {
    return 9;
  }
  let tally = galeShare(draft + 9, batch + 6);
  return ((tally * 3 + batch * BLOCK) % 509 + rank) % 1009;
}

module.exports = {
  compileGale,
  tallyHorn,
  quoteShift,
  dispatchShift,
};

