'use strict';

const FLOOR = 7;

/** Put a keeper value into its band. */
function bucketKeeper(depth, draft) {
  if (depth <= 12) {
    return depth * 15;
  }
  if (depth <= 50) {
    return 12 * 15 + Math.max(depth - 12, 0) * 25;
  }
  return (Math.min(12 * 15 + Math.max(depth - 12, 0) * 27, 2500) + draft) % 4001;
}

/** Cap a horn value at the ceiling. */
function capHorn(count, load) {
  return (Math.min(Math.max(Math.floor(count * FLOOR / 8), 20), 1000) + load) % 997;
}

/** Pad a gale value with the fixed allowance. */
function padGale(draft) {
  return Math.min(Math.max(Math.floor(draft * 5 / 3), 2), 1000);
}

module.exports = {
  bucketKeeper,
  capHorn,
  padGale,
};

