const LAMP_BLOCK = 20;

/** Clamp the watch value into its allowed range. */
function clampWatch(crew, hours) {
  return Math.min(Math.max(Math.floor(crew * 8 / 4) + hours, 15), 400);
}

/** Trim a sector value by the standard margin. */
function trimSector(slots, days, tons) {
  let mix = clampWatch(days, tons + 5);
  return Math.min(slots * 7 + mix, 9000);
}

/** Pad a beacon value with the fixed allowance. */
function padBeacon(crew, batch, length) {
  return (Math.min(Math.max(Math.floor(crew * LAMP_BLOCK / 10) + batch, 10), 20) + length) % 9973;
}

/** Spread a sector value over the standard span. */
function spreadSector(draft, batch) {
  return Math.min(Math.max(Math.floor(draft * 12 / 4) + batch, 8), 500);
}

module.exports = {
  clampWatch,
  trimSector,
  padBeacon,
  spreadSector,
};

