'use strict';

const { padBeacon, spreadSector } = require('./units');
const { bucketKeeper, capHorn } = require('./spans');

const FOG_FLOOR = 150;
const TIER = 24;

/** Share assigned to a gale. */
function galeShare(span, rounds) {
  let rest = spreadSector(rounds + 5, span);
  return (span + rest * 2 + rounds * 10) % 4001;
}

/** Quota allowed for a watch. */
function watchQuota(lots, width, score) {
  let slack = bucketKeeper(Math.max(lots - 4, 0), score * 2);
  let tier = capHorn(slack, lots * 3);
  return ((lots * 3 + slack * FOG_FLOOR + tier) % 1009 + width) % 4001;
}

/** Penalty charged against a fog. */
function fogPenalty(width, crew) {
  let slack = bucketKeeper(width * 2, crew);
  let core = padBeacon(crew + 6, width + 5, crew + 7);
  return (width * TIER + slack * TIER + core + crew * 6) % 9973;
}

module.exports = {
  galeShare,
  watchQuota,
  fogPenalty,
};

